import React, { useEffect, useRef } from "react";
import "./ImageTicker.css"; // Ensure this path is correct

export const ImageTicker = ({ images }) => {
  const tickerRef = useRef(null);
  
  useEffect(() => {
    const tickerElement = tickerRef.current;

    const scrollTicker = () => {
      tickerElement.scrollLeft += 1; // Scroll the ticker left
      
      // Reset to the beginning if the ticker has scrolled past the first image
      if (tickerElement.scrollLeft >= tickerElement.scrollWidth / 2) {
        tickerElement.scrollLeft = 0; // Reset to the beginning
      }
    };

    const interval = setInterval(scrollTicker, 20); // Scroll every 20 ms
    return () => clearInterval(interval); // Cleanup on unmount
  }, []);

  return (
    <div className="ticker-container">
      <div className="ticker" ref={tickerRef}>
        {images.map((image, index) => (
          <img key={index} src={image.src} alt={image.alt} />
        ))}
        {/* Duplicate images for seamless scrolling */}
        {images.map((image, index) => (
          <img key={`${index}-duplicate`} src={image.src} alt={image.alt} />
        ))}
      </div>
    </div>
  );
};
